package io.github.flipendo.spike;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
public class BundledHDTests {
 static class Assets implements BundledHD.Assets {Map<String,byte[]> files=new LinkedHashMap<>();int opens;public String[] list(String path){List<String> names=new ArrayList<>();for(String name:files.keySet())if(name.startsWith(path+"/"))names.add(name.substring(path.length()+1));return names.toArray(new String[0]);}public InputStream open(String path)throws IOException{if(!files.containsKey(path))throw new FileNotFoundException(path);opens++;return new ByteArrayInputStream(files.get(path));}}
 public static void main(String[] args)throws Exception{byte[] dds=null;try(ZipFile z=new ZipFile(args[0])){for(Enumeration<? extends ZipEntry> en=z.entries();en.hasMoreElements();){ZipEntry e=en.nextElement();if(e.getName().endsWith(".dds")){dds=z.getInputStream(e).readAllBytes();break;}}}File base=Files.createTempDirectory("bundled-hd-test-").toFile();try{File cache=new File(base,"cache");cache.mkdirs();for(boolean hp2:new boolean[]{false,true}){File root=new File(base,hp2?"hp2":"hp1");root.mkdirs();Assets assets=new Assets();String folder="bundled-hd/"+(hp2?"hp2":"hp1");assets.files.put(folder+"/.stamp","stamp-v1".getBytes("UTF-8"));for(int i=0;i<6;i++)assets.files.put(folder+"/0"+i+".zip",LauncherTests.module(hp2?"HP2":"HP1","Textures/Test/Item"+i+".dds",dds,false));LauncherTests.ok(BundledHD.apply(root,hp2,cache,assets,t->{},false)==0);LauncherTests.ok(assets.opens==0);LauncherTests.ok(HDPackInstaller.installed(root).isEmpty());LauncherTests.ok(BundledHD.apply(root,hp2,cache,assets,t->{},true)==6);LauncherTests.ok(HDPackInstaller.installed(root).size()==6);int before=assets.opens;LauncherTests.ok(BundledHD.ensure(root,hp2,cache,assets,t->{},false)==0);LauncherTests.ok(assets.opens==before+1);BundledHD.apply(root,hp2,cache,assets,t->{},false);LauncherTests.ok(BundledHD.ensure(root,hp2,cache,assets,t->{},false)==0);LauncherTests.ok(HDPackInstaller.installed(root).isEmpty());LauncherTests.ok(BundledHD.ensure(root,hp2,cache,assets,t->{},true)==6);LauncherTests.ok(HDPackInstaller.installed(root).size()==6);assets.files.put(folder+"/.stamp","stamp-v2".getBytes("UTF-8"));LauncherTests.ok(BundledHD.ensure(root,hp2,cache,assets,t->{},false)==6);LauncherTests.ok(BundledHD.read(new File(root,BundledHD.MARKER)).equals("stamp-v2"));assets.files.remove(folder+"/00.zip");assets.files.put(folder+"/.stamp","stamp-v3".getBytes("UTF-8"));LauncherTests.rejects(()->BundledHD.ensure(root,hp2,cache,assets,t->{},false));LauncherTests.ok(BundledHD.read(new File(root,BundledHD.MARKER)).equals("stamp-v2"));LauncherTests.ok(HDPackInstaller.installed(root).size()==6);}
 System.out.println("PASS "+LauncherTests.checks+" bundled-HD checks: both profiles, disabled default, explicit enable, repeat launch skip, removal stays disabled, restore, version update, incomplete bundle preserves prior state.");}finally{HDPackInstaller.erase(base);}}
}
